import{_ as a,a0 as l,w as d,s as r,I as e,x as t,a1 as i,A as n,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何在 sudo 運行的命令中防止使用參數 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 sudo 運行的命令中防止使用參數 | LCTT (202210) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 sudo 運行的命令中防止使用參數 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 sudo 運行的命令中防止使用參數 | LCTT (202210) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202210/20220915 How To Prevent Command Arguments With Sudo In Linux","title":"如何在 sudo 運行的命令中防止使用參數","tag":"202210","desc":""},"relativePath":"202210/20220915 How To Prevent Command Arguments With Sudo In Linux.md","filePath":"[post].md"}'),u={name:"202210/20220915 How To Prevent Command Arguments With Sudo In Linux.md"};function h(g,s,m,k,b,c){const o=l("Link");return d(),r("div",null,[s[24]||(s[24]=e("h1",{id:"如何在-sudo-運行的命令中防止使用參數",tabindex:"-1"},[t("如何在 sudo 運行的命令中防止使用參數 "),e("a",{class:"header-anchor",href:"#如何在-sudo-運行的命令中防止使用參數","aria-label":"Permalink to “如何在 sudo 運行的命令中防止使用參數”"},"​")],-1)),s[25]||(s[25]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202210/04/224059k9jl5kzhlhw5d98j.jpg",alt:""})],-1)),s[26]||(s[26]=e("blockquote",null,[e("p",null,[t("允許用户使用 "),e("code",null,"sudo"),t(" 運行命令，但不帶命令列參數。")])],-1)),e("p",null,[s[1]||(s[1]=t("在之前的文章，我們學習瞭如何 ",-1)),i(o,{href:"https://ostechnix.com/run-programs-in-a-directory-via-sudo/"},{default:n(()=>[...s[0]||(s[0]=[t("通過 sudo 以 root 身份運行目錄中的命令",-1)])]),_:1}),s[2]||(s[2]=t("。在這篇指南中，我們將學習如何在 Linux 中 ",-1)),s[3]||(s[3]=e("strong",null,"防止 sudo 運行的命令使用參數",-1)),s[4]||(s[4]=t("。即我們允許一個用户使用 ",-1)),s[5]||(s[5]=e("code",null,"sudo",-1)),s[6]||(s[6]=t(" 運行特權級命令，但是 ",-1)),s[7]||(s[7]=e("strong",null,"不帶命令列參數",-1)),s[8]||(s[8]=t("。",-1))]),s[27]||(s[27]=p('<h3 id="背景介紹" tabindex="-1">背景介紹 <a class="header-anchor" href="#背景介紹" aria-label="Permalink to “背景介紹”">​</a></h3><p>你已經知道了，每個命令執行一個特定操作有不同的選項。讓我們以 <code>ls</code> 命令為例。</p><p><code>ls</code> 命令會羅列文件夾中的內容，對嗎？沒錯。<code>ls</code> 命令附帶了一些命令列選項和標誌。例如，你可以用 <code>ls</code> 命令的 <code>-a</code> 標誌羅列文件夾中的所有內容（包括隱藏文件）。</p><p>在這份簡要指南中，我們將明白如何允許用户通過 <code>sudo</code> 運行 <code>ls</code> 命令，但是不能使用命令列選項或者標誌。我講清楚了嗎？接下來讓我來展示一下如何做到這點。</p><h3 id="防止使用-sudo-參數" tabindex="-1">防止使用 sudo 參數 <a class="header-anchor" href="#防止使用-sudo-參數" aria-label="Permalink to “防止使用 sudo 參數”">​</a></h3><p>以 <code>root</code> 用户身份編輯 <code>/etc/sudoers</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@Almalinux8CT ~]# visudo</span></span></code></pre></div><p>添加下面一行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>user1   ALL=(root)      /usr/bin/ls &quot;&quot;</span></span></code></pre></div><p><img src="https://ostechnix.com/wp-content/uploads/2022/09/Deny-Command-Arguments-With-Sudo.png" alt="Deny Command Arguments With Sudo"></p><p>要注意這裏 <code>ls</code> 之後的 <strong>雙引號</strong>。雙引號會屏蔽用户在給定命令之後輸入的參數（比如 <code>ls</code> 命令）。在上面的命令中，<code>user1</code> 能夠以 <code>root</code> 身份運行 <code>ls</code> 命令，但是不能使用 <code>ls</code> 命令的選項以及標誌。你可以選擇其他的指令進行嘗試。保存該文件並關閉。</p><p>現在，以 <code>user1</code> 的身份登錄系統，並嘗試以管理員身份運行 <code>ls</code> 命令，不要添加任何選項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[user1@Almalinux8CT ~]$ sudo -u root ls -a</span></span></code></pre></div><p>或許你會遇到下面的報錯：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Sorry, user user1 is not allowed to execute &#39;/bin/ls -a&#39; as root on Almalinux8CT.</span></span></code></pre></div><p>不過你可以不添加參數來運行 <code>ls</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[user1@Almalinux8CT ~]$ sudo -u root ls</span></span></code></pre></div><p><img src="https://ostechnix.com/wp-content/uploads/2022/09/Prevent-Command-Arguments-With-Sudo.png" alt="Prevent Command Arguments With Sudo"></p><h3 id="防止所有用户使用命令參數" tabindex="-1">防止所有用户使用命令參數 <a class="header-anchor" href="#防止所有用户使用命令參數" aria-label="Permalink to “防止所有用户使用命令參數”">​</a></h3><p>上述例子像你展示瞭如何阻止用户以管理員身份運行帶有參數的命令。你是否想要對所有用户應用該規則呢？很簡單！只需要在 <code>/etc/sudoers</code> 文件中添加一行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ALL   ALL=(root)      /usr/bin/ls &quot;&quot;</span></span></code></pre></div><p>現在，系統中的所有用户都可以運行不帶參數的 <code>ls</code> 命令。</p><p>想要恢復默認設置，只需要刪除最後的雙引號，或者刪除整行。</p><p>查看幫助手冊，瞭解更多。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man sudoers</span></span></code></pre></div><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>在這份指南中，我們學習瞭如何允許用户以管理員身份運行命令，但是不能添加任何命令參數。這樣可以限制用户誤用一些命令列參數。</p><hr>',28)),e("p",null,[s[10]||(s[10]=t("via: ",-1)),i(o,{href:"https://ostechnix.com/prevent-command-arguments-with-sudo/"},{default:n(()=>[...s[9]||(s[9]=[t("https://ostechnix.com/prevent-command-arguments-with-sudo/",-1)])]),_:1})]),e("p",null,[s[15]||(s[15]=t("作者：",-1)),i(o,{href:"https://ostechnix.com/author/sk/"},{default:n(()=>[...s[11]||(s[11]=[t("sk",-1)])]),_:1}),s[16]||(s[16]=t(" 選題：",-1)),i(o,{href:"https://github.com/lkxed"},{default:n(()=>[...s[12]||(s[12]=[t("lkxed",-1)])]),_:1}),s[17]||(s[17]=t(" 譯者：",-1)),i(o,{href:"https://github.com/Donkey-Hao"},{default:n(()=>[...s[13]||(s[13]=[t("Donkey-Hao",-1)])]),_:1}),s[18]||(s[18]=t(" 校對：",-1)),i(o,{href:"https://github.com/wxy"},{default:n(()=>[...s[14]||(s[14]=[t("wxy",-1)])]),_:1})]),e("p",null,[s[21]||(s[21]=t("本文由 ",-1)),i(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[19]||(s[19]=[t("LCTT",-1)])]),_:1}),s[22]||(s[22]=t(" 原創編譯，",-1)),i(o,{href:"https://linux.cn/"},{default:n(()=>[...s[20]||(s[20]=[t("Linux中國",-1)])]),_:1}),s[23]||(s[23]=t(" 榮譽推出",-1))])])}const T=a(u,[["render",h]]);export{C as __pageData,T as default};
